    const number = case_no?.trim();
    if (!id && !number) return errorResult("Bitte case_id oder case_no angeben.");
    let caseRequest = scoped.client.from("cases").select("id, case_no, project_name, client_name, customer_no, status, due_at, created_at, note, closure_summary, assignee_id, department_id, project_id").eq("deleted", false).limit(1).maybeSingle();
    caseRequest = id ? caseRequest.eq("id", id) : caseRequest.eq("case_no", number);
